VALUES ('d51fcd1e-bb6b-4c37-97a0-657d413505f9'::uuid, 'f6d51727-bd1e-4cc3-a839-94208cc12f41'::uuid, 'builder_f6d51727bd1e', '-- 树契约: material_no=子 / parent_no=父 + :total_material_no; 边式全子件 + 根分支
SELECT
  dqmb.input_material_no AS material_no,
  dqmb.material_no AS parent_no,
  dqmb.input_material_no AS hf_part_no,
  dqmb.material_no AS "_物料BOM_销售料号",
  dqmb.item_seq AS "_物料BOM_项次",
  dqmb.input_material_no AS "_物料BOM_投入料号",
  dqmb.unit_weight AS "_物料BOM_单重",
  dqmb.output_material_type AS "_物料BOM_产出料号类型",
  dqmb.component_qty AS "_物料BOM_组成数量",
  dqmb.gross_weight AS "_物料BOM_材料毛重",
  dqmb.net_weight AS "_物料BOM_材料净重",
  dqmb.weight_unit AS "_物料BOM_重量单位",
  dqmb.material_ratio AS "_物料BOM_材料占比（%）",
  dqmb.loss_rate AS "_物料BOM_损耗率（%）",
  dqmb.defect_rate AS "_物料BOM_不良率（%）"
FROM ds_quote_material_bom dqmb
WHERE dqmb.input_material_no = ANY(:total_material_no)
UNION ALL
-- 根分支：本单闭包里无父边的成品自身（树根，parent_no 恒 NULL）
SELECT
  dqm.material_no,
  NULL::text,
  dqm.material_no,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
FROM ds_quote_material dqm
WHERE dqm.material_no = ANY(:total_material_no)
  AND NOT EXISTS (SELECT 1 FROM ds_quote_material_bom dqmb2 WHERE dqmb2.input_material_no = dqm.material_no)
ORDER BY parent_no, material_no, "_物料BOM_项次"', '[{"name": "material_no", "dataType": "varchar", "nullable": true}, {"name": "parent_no", "dataType": "varchar", "nullable": true}, {"name": "hf_part_no", "dataType": "varchar", "nullable": true}, {"name": "_物料BOM_销售料号", "dataType": "varchar", "nullable": true}, {"name": "_物料BOM_项次", "dataType": "int4", "nullable": true}, {"name": "_物料BOM_投入料号", "dataType": "varchar", "nullable": true}, {"name": "_物料BOM_单重", "dataType": "numeric", "nullable": true}, {"name": "_物料BOM_产出料号类型", "dataType": "varchar", "nullable": true}, {"name": "_物料BOM_组成数量", "dataType": "numeric", "nullable": true}, {"name": "_物料BOM_材料毛重", "dataType": "numeric", "nullable": true}, {"name": "_物料BOM_材料净重", "dataType": "numeric", "nullable": true}, {"name": "_物料BOM_重量单位", "dataType": "varchar", "nullable": true}, {"name": "_物料BOM_材料占比（%）", "dataType": "numeric", "nullable": true}, {"name": "_物料BOM_损耗率（%）", "dataType": "numeric", "nullable": true}, {"name": "_物料BOM_不良率（%）", "dataType": "numeric", "nullable": true}]'::jsonb, '{total_material_no}'::text[], 'COMPONENT', 'ACTIVE', NULL, NULL, now(), now(), '{"columns": [{"isAmount": null, "fieldName": "销售料号", "fieldType": null, "inSubtotal": null, "viewColumn": "_物料BOM_销售料号", "sourceColumn": "material_no", "resolvedRoles": ["ROW_KEY"], "sourceNodeKey": "MATERIAL_BOM", "resolvedDataType": "TEXT"}, {"isAmount": null, "fieldName": "项次", "fieldType": null, "inSubtotal": null, "viewColumn": "_物料BOM_项次", "sourceColumn": "item_seq", "resolvedRoles": ["SORT"], "sourceNodeKey": "MATERIAL_BOM", "resolvedDataType": "NUMBER"}, {"isAmount": null, "fieldName": "投入料号", "fieldType": null, "inSubtotal": null, "viewColumn": "_物料BOM_投入料号", "sourceColumn": "input_material_no", "resolvedRoles": ["PART_NO", "ROW_KEY"], "sourceNodeKey": "MATERIAL_BOM", "resolvedDataType": "TEXT"}, {"isAmount": null, "fieldName": "单重", "fieldType": null, "inSubtotal": null, "viewColumn": "_物料BOM_单重", "sourceColumn": "unit_weight", "resolvedRoles": [], "