VALUES ('9f856a52-f911-4d6d-be06-ae1ff3987c79'::uuid, '875a5c9f-3579-4c9d-b600-1791ff25afa7'::uuid, 'f6d51727-bd1e-4cc3-a839-94208cc12f41'::uuid, '物料BOM', 13, now(), '[]'::jsonb, '{}'::jsonb, NULL, NULL::jsonb)
ON CONFLICT (id) DO NOTHING;

DO $$
DECLARE
  n int;
  problems text := '';
BEGIN
  SELECT count(*) INTO n FROM template_component WHERE template_id = '875a5c9f-3579-4c9d-b600-1791ff25afa7'::uuid;
  IF n <> 14 THEN
    problems := problems || format('[1] template_component 期望 %s，实得 %s; ', 14, n);
  END IF;
  SELECT count(*) INTO n FROM component_sql_view v
   WHERE v.component_id IN (SELECT component_id FROM template_component WHERE template_id = '875a5c9f-3579-4c9d-b600-1791ff25afa7'::uuid)
     AND v.builder_version IS NULL;
  IF n > 0 THEN
    problems := problems || format('[2] %s 个组件视图 builder_version 为空（AC-7② 要求全部由取数配置器生成）; ', n);
  END IF;
  SELECT count(*) INTO n FROM component_sql_view v
   WHERE v.component_id IN (SELECT component_id FROM template_component WHERE template_id = '875a5c9f-3579-4c9d-b600-1791ff25afa7'::uuid)
     AND v.sql_template ILIKE '%f_material_element_price%';
  IF n > 0 THEN
    problems := problems || format('[3] %s 个组件视图仍在用 f_material_element_price，D-27 要求走 f_customer_element_price（前者的候选料号只从 V6 的 material_bom_item ∪ element_bom_item 取，新导入的 ds_ 料号恒不在候选集，症状是「元素单价整列空」）; ', n);
  END IF;
  IF problems <> '' THEN
    RAISE EXCEPTION 'task-260907 模板种子自检失败：%', problems;
  END IF;
  -- TODO(AC-8 解封后补): 加肯定式守卫「材质元素页签必须绑 f_customer_element_price」——
  --   现有 [3] 只拦「用错函数」，拦不住「两个函数都没用」。
END $$;
